TLM.f("Sancti/12-26",{"officium":"S. Stephani Protomartyris","rule":["ex C2;","Gloria","Credo","Prefatio=Nat"],"fallback":"Commune/C2","sections":{"Introitus":[{"k":"ref","la":"Ps 118:23; 118:86; 118:23"},{"k":"text","la":"Sedérunt príncipes, et advérsum me loquebántur: et iníqui persecúti sunt me: ádjuva me, Dómine, Deus meus, quia servus tuus exercebátur in tuis justificatiónibus."},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beati immaculáti in via, qui ámbulant in lege Dómini,"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sedérunt príncipes, et advérsum me loquebántur: et iníqui persecúti sunt me: ádjuva me, Dómine, Deus meus, quia servus tuus exercebátur in tuis justificatiónibus."}],"Oratio":[{"k":"text","la":"Da nobis, quaésumus, Dómine, imitári quod cólimus: ut discámus et inimícos dilígere; quia eius natalícia celebrámus, qui novit étiam pro persecutóribus exoráre Dóminum nostrum Iesum Christum, Fílium tuum:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Act 6:8-10; 7:54-59"},{"k":"text","la":"In diebus illis: Stéphanus plenus grátia et fortitúdine, faciébat prodígia et signa magna in pópulo. Surrexérunt autem quidam de synagóga, quæ appellátur Libertinórum, et Cyrenénsium, et Alexandrinórum, et eórum, qui erant a Cilícia et Asia, disputántes cum Stéphano: et non póterant resístere sapiéntiæ et Spirítui, qui loquebátur. Audiéntes autem hæc, dissecabántur córdibus suis, et stridébant déntibus in eum. Cum autem esset Stéphanus plenus Spíritu Sancto, inténdens in cœlum, vidit glóriam Dei, et Jesum stantem a dextris Dei. Et ait: Ecce, vídeo cœlos apértos, et Fílium hóminis stantem a dextris Dei. Exclamántes autem voce magna continuérunt aures suas, et ímpetum fecerunt unanímiter in eum. Et ejiciéntes eum extra civitatem, lapidábant: et testes deposuérunt vestiménta sua secus pedes adolescéntis, qui vocabátur Saulus. Et lapidábant Stéphanum invocántem et dicéntem: Dómine Jesu, súscipe spíritum meum. Pósitis autem génibus, clamávit voce magna, dicens: Dómine, ne státuas illis hoc peccátum. Et cum hoc dixísset, obdormívit in Dómino."}],"Graduale":[{"k":"ref","la":"Ps 118:23; 118:86"},{"k":"text","la":"Sedérunt príncipes, et advérsum me loquebántur: et iníqui persecúti sunt me."},{"k":"ref","la":"Ps 6:5"},{"k":"text","la":"Adjuva me, Dómine, Deus meus: salvum me fac propter misericórdiam tuam."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Act 7:56"},{"k":"text","la":"Vídeo cœlos apértos, et Jesum stantem a dextris virtútis Dei. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Act 7:55"},{"k":"text","la":"Vídeo cœlos apértos, et Jesum stantem a dextris virtútis Dei. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Matthǽum"},{"k":"ref","la":"Matt 23:34-39"},{"k":"text","la":"In illo témpore: Dicébat Jesus scribis et pharisǽis: Ecce, ego mitto ad vos prophétas, et sapiéntes, et scribas, et ex illis occidétis et crucifigétis, et ex eis flagellábitis in synagógis vestris, et persequémini de civitáte in civitátem: ut véniat super vos omnis sanguis justus, qui effúsus est super terram, a sánguine Abel justi usque ad sánguinem Zacharíæ, filii Barachíæ, quem occidístis inter templum et altáre. Amen, dico vobis, vénient hæc ómnia super generatiónem istam. Jerúsalem, Jerúsalem, quæ occídis prophétas, et lápidas eos, qui ad te missi sunt, quóies vólui congregáre fílios tuos, quemádmodum gallína cóngregat pullos suos sub alas, et noluísti? Ecce, relinquétur vobis domus vestra desérta. Dico enim vobis, non me vidébitis ámodo, donec dicátis: Benedíctus, qui venit in nómine Dómini."}],"Offertorium":[{"k":"ref","la":"Act 6:5; 7:59"},{"k":"text","la":"Elegérunt Apóstoli Stéphanum Levítam, plenum fide et Spíritu Sancto: quem lapidavérunt Judæi orántem, et dicéntem: Dómine Jesu, áccipe spíritum meum, allelúja."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, múnera pro tuórum commemoratióne Sanctórum: ut, sicut illos pássio gloriósos effécit; ita nos devótio reddat innócuos."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Act 7:55; 7:58; 7:59"},{"k":"text","la":"Vídeo cœlos apértos, et Jesum stantem a dextris virtútis Dei: Dómine Jesu, accipe spíritum meum, et ne státuas illis hoc peccátum."}],"Postcommunio":[{"k":"text","la":"Auxiliéntur nobis, Dómine, sumpta mystéria: et, intercedénte beáto Stéphano Mártyre tuo, sempitérna protectióne confírment."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut nos Unigéniti tui nova per carnem Natívitas líberet; quos sub peccáti jugo vetústa sérvitus tenet."},{"k":"macro","name":"Per eundem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Obláta, Dómine, múnera, nova Unigéniti tui Nativitáte sanctífica: nosque a peccatórum nostrorum máculis emúnda."},{"k":"macro","name":"Per eundem"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Nativitatis"},{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut natus hodie Salvátor mundi, sicut divínæ nobis generatiónis est auctor; ita et immortalitátis sit ipse largítor:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"f5a296a39a3fc703":{"t":"Ps 118, 23 i 68 i 1\n(Ps 118, 23 i 68) Prvaci naroda sjede, vijećaju protiv mene i nepravedno me progone. Pomozi mi, Gospodine Bože moj, jer sluga tvoj izvršuje tvoje naloge. (Ps 118, 1) Blago neokaljanima na životnom putu, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.","kn":"(Ps. 118, 23). Sjedoše knezovi i dogovarahu se protiv mene, i zločinci me progoniše. Pomozi mi. Gospodine, Bože moj, jer se sluga Tvoj vježbao u opravdanjima Tvojim. (Ps. isti). Blago onima, koji su čista života, koji hode u zakonu Gospodnjem. Slava Ocu . . . Sjedoše knezovi . . .","knRef":"Kniewald 1942, str. 460–461 (snimka 231) (OCR)"},"5bd07e06f9f19d68":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine, nasljedovati što častimo, da naučimo ljubiti i neprijatelje, jer slavimo dan kad se za nebo rodio onaj koji je znao i za progonitelje moliti Gospodina našega Isusa Krista Sina tvoga:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj nam, molimo. Gospodine, nasljedovati, što častimo, da naviknemo neprijatelje ljubiti, jer slavimo rođendan^ onoga, ko-jl je znao i za progonitelje svoje moliti Gospodina našega Isus Krista, Sina Tvojega: Koji s Tobom živi i kraljuje , . .","knRef":"Kniewald 1942, str. 460–461 (snimka 231) (OCR)"},"34458bb63da088c3":{"t":"Dj 6, 8-10 i 7, 54-59\nČitanje Djela apostolskih. U one dane Stjepan, pun milosti i jakosti, činio je u narodu velika čudesa i znakove. Tada se počnu prepirati sa Stjepanom neki iz zbornice libertin–ske, cirinejske, alelcsandnijske i drugi iz Cilicije i Azije. Ali nisu mogli odoljeti mudrosti i Duhu koji je govorio iz njega. Kad su ga čuli, kipjeli su od srdžbe u svojim srcima i škripali zubima na njega. – Stjepan pun Duha Svetoga, zagleda se u nebo i vidje Božju slavu i Isusa gdje stoji s desne Bogu, pa reče: »–Evo vidim otvoreno nebo i Sina čovječjega s desne Bogu.« A oni strašno vičući začepe uši i svi zajedno navale na njega. Izbace ga iz grada i kamenuju, a svjedoci odlože svoje haljine do nogu mladića Savla. I kamenuju Stjepana dok je molio: »Gospodine Isuse, primi moj duh!« Pade zatim na koljena i snažnim glasom povika: »Gospodine, ne uzmi im ovo za grijeh!« I kad to reče, usnu u Gospodinu.","kn":"Čitanje Djela apostolskih (6, 8-10; 7, 54-59). U one dane Stjepan ipun milosti i jakosti činio je među narodom velika čudesa i znakove. Tada se dignu da se prepiru sa Stjepanom neki iz zbornice, koja se zove hbertinska i cirenska i aleksandrijska i od onih, koji su bili iz Cicilije i Azije. Ali ne mogoše odoljeti mudrosti i Duhu, kojim je govorio. Kad su to čuli, kipjeli su od srdžbe u svojim srcima i škripali zubima na njega. A Stjepan, pun Duha Svetoga, zagleda se u nebo i vidje slavu Božju i Isusa, gdje stoji s desne Božje i reče; Evo, vidim otvoreno nebo i Sinai čovječjega, gdje stoji s desne Božje! A oni vičući svim grlom začepe svoje uši i svi zajedno navale na njega. Izbaciše ga iz grada i kamenovaše, a svjedoci odložiše svoje haljine do nogu mladića, imenom Savla. I kamenuju Stjepana, koji je zazivao i govorio: Gospodine Isuse, primi moj duh! Pade zatim na koljena i glasno zavika: Gospodine, ne uzmi lm ovoga za grijeh! I kad to reče, usnu u Gospodinu.","knRef":"Kniewald 1942, str. 460–461 (snimka 231) (OCR)"},"3e749ac80764a9b9":{"t":"Ps 118, 23 i 68 i 6\nPrvaci naroda sjede, vijećaju protiv mene i nepravedno me progone. Pomozi mi, Gospodine Bože moj, spasi me radi svoga milosrđa.\n\nDj 7, 56\n<i>Aleluja</i>, <i>aleluja</i>.\nVidim otvoreno nebo i Isusa gdje stoji s desne silnoga Boga. <i>Aleluja</i>.","kn":"(Ps. 118), Sjedoše knezovi i dogovarahu se protiv mene 1 zločinci me progoniše. Pomozi mi, Gospodine, Bože moj; spasi me zaradi milosrđa Tvoga! Aleluja, aleluja. (Dj. ap. 7). Vidim","knRef":"Kniewald 1942, str. 460–461 (snimka 231) (OCR)"},"33eea978573358a5":{"t":"Mt 23, 34-39\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: reče Isus književnicima i farizejima: Evo ja vam šaljem proroke, mudrace i književnike. Vi ćete jedne od njih ubiti i raspeti, druge po svojim zbornicama bičevati i progoniti od grada do grada. Zato će na vas pasti sva pravedna krv prolivena na zemlji, od krvi pravednog Abela do krvi Barakijina sina Zakarije kojega ste ubili između hrama i oltara. Zaista vam kažem, sve će se ovo dogoditi već ovom naraštaju. – Jeruzaleme, koji ubijaš proroke i kamenuješ one koji su ti poslani! Koliko sam puta htio skupiti tvoju djecu, kao što kvočka skuplja svoje piliće pod krila, ali ti nisi htio! Evo, ostat će vam pusta vaša kuća. Jer znajte da me više nećete vidjeti, dok ne rečete: Blagoslovljen koji dolazi u dme Gospodnje!","kn":"t Slijedi sveto evanđelje po Mateju (23, 34-39). U ono vrijeme ■ reče Isus književnicima, i farizejima; Evo, ja vam šaljem proroke i mudrace i književnike, a vi ćete jedne od njih ubiti i raspeti, a druge bičevati po svojim zbornicama i progoniti od grada do grada, da na vas dođe sva pravedna krv, koja, je prolivena na zemlji od krvi pravednoga Abela do krvi Zaharije, sina Barahijina, kojega ubiste između hrama i oltara. ^ Zaista vam kažem, sve će to doći na ovaj naraštaj. Jeruzaleme, Jeruzaleme, koji ubijaš proroke i kamenuješ one, koji su ti poslani! Koliko sam puta htio skupiti tvoju djecu kao što kvočka skuplja svoje piliće pod krila, ali ti nijesi htio! Evo, ostat će vam pusta vaša kuća. Jer ikažem vam: Odsad me ne ćete vidjeti, dok ne rečete: Blagoslovljen, koji dolazi u ime Gospodnje!","knRef":"Kniewald 1942, str. 462–463 (snimka 232) (OCR)"},"fda15413773b75ec":{"t":"Dj 6, 5 et 7, 59\nIzabraše apostoli levitu Stjepana puna vjere i Duha Svetoga. Njega su Židovi kamenovali dok je molio i govorio: »Gospodine Isuse, primi moj duh!« Aleluja.","kn":"(Dj. ap. 7 i 8). Izabraše apostoli Stjepana levitu, puna vjere i Duha Svetoga, koga kamenovaše Židovi, dok je molio i govorio: Gospodine Isuse, primi duh moj! Aleluja.","knRef":"Kniewald 1942, str. 462–463 (snimka 232) (OCR)"},"6f5e2f839a09c703":{"t":"Primi, Gospodine, darove u spomen tvojih svetaca i daj nam da nas pobožnost učini pravednima kao što je mučeništvo njih učinilo slavnima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, darove za uspomenu svetih Tvojih: kako je njih muka učinila slavnima, tako da i naš pobožnost učini slobodnima od grijeha, po G. n.","knRef":"Kniewald 1942, str. 462–463 (snimka 232) (OCR)"},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"99932d920206a39e":{"t":"Dj 7, 56 i 59-60\nVidim otvoreno nebo i Isusa gdje stoji s desne silnoga Boga. Gospodine Isuse, primi moj duh i ne uzmi im ovo za grijeh!","kn":"(Dj.- ap. 7, 55): Vidim nebesa otvorena i Isusa, gdje stoji s desne strane sile Božje: Gospodine Isuse, primi duh moj i ne primi im ovo za grijeh!","knRef":"Kniewald 1942, str. 462–463 (snimka 232) (OCR)"},"f4064c071d239c6e":{"t":"<i>Pomolimo se</i>.\nPrimljena otajstva, Gospodine, bila nam na pomoći i zagovorom blaženoga Stjepana, tvoga mučenika, neka nas neprestano štite i jačaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nam pomognu. Gospodine, prlm-^ Ijena -otajstva i po, zagovoru blaženoga mučenika Stjepana neka nas utvrde sveudiljnim o-kriljem. Po Gospođinu ...","knRef":"Kniewald 1942, str. 462–463 (snimka 232) (OCR)"}}});
